-- SEO-GRADE1 — Technical data enrichment for the ten published grade pages.
--
-- Adds sourced mechanical-property, chemical-composition and family-comparison
-- tables to each public grade page, plus two data-bearing FAQs and the
-- manufacturer datasheet used as evidence. Search-facing title and description
-- now state the numbers people look for.
--
-- Editorial contract is unchanged: values are attributed to a manufacturer
-- datasheet and its product standard, never presented as the full normative
-- text, and no equivalence or substitution is asserted.
--
-- Content-only migration: no schema, RLS or RPC change. `editorial_sections`
-- items gain an optional `table` object {caption, columns, rows, note} which
-- the public page renders; readers that ignore it keep working.
-- Idempotent: a page already carrying the mechanical section is skipped.

create function pg_temp.seo_grade1_apply(
  p_slug text,
  p_marker text,
  p_title text,
  p_description text,
  p_sections jsonb,
  p_faq jsonb,
  p_sources jsonb
) returns void
language plpgsql
as $$
declare
  v_count integer;
begin
  update public.steel_knowledge_grade_pages p
  set
    seo_title=p_title,
    seo_description=p_description,
    editorial_sections=p_sections || p.editorial_sections,
    faq=p.faq || p_faq,
    source_references=p.source_references || p_sources,
    draft_payload=p.draft_payload || jsonb_build_object(
      'seo_title',p_title,
      'seo_description',p_description,
      'editorial_sections',p_sections || p.editorial_sections,
      'faq',p.faq || p_faq,
      'source_references',p.source_references || p_sources
    ),
    editorial_version=p.editorial_version+1,
    draft_version=greatest(p.draft_version,p.editorial_version+1),
    last_reviewed_at='2026-11-15'::date,
    updated_at=now()
  where p.slug=p_slug
    and p.page_status='published'
    and not exists (
      select 1
      from jsonb_array_elements(p.editorial_sections) s
      where s->>'heading'=p_marker
    );
  get diagnostics v_count=row_count;
  raise notice 'SEO-GRADE1 %: % row(s) updated', p_slug, v_count;
end;
$$;

-- P235GH / 1.0345 — source: https://www.mannesmann.com/en/knowledge/standards-materials/hfi-welded-steel-pipes/en-10217-2/p235gh-mlp-mgr.html
